// StudentLogin.js
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { collection, getDocs } from "firebase/firestore";
import { getAuth, signInWithEmailAndPassword } from "firebase/auth";
import { db } from "../../firebaseConfig";
import "./StudentLogin.css";

const StudentLogin = () => {
  const [emailOrUsername, setEmailOrUsername] = useState("");
  const [password, setPassword] = useState("");
  const [studentClass, setStudentClass] = useState(""); // State for the class input
  const [error, setError] = useState(""); // State for error message
  const [students, setStudents] = useState([]); // Store students data
  const navigate = useNavigate();

  const auth = getAuth();

  // Fetch student data from Firestore
  useEffect(() => {
    const fetchStudents = async () => {
      const studentsCollectionRef = collection(db, "students");
      const data = await getDocs(studentsCollectionRef);
      setStudents(data.docs.map((doc) => ({ ...doc.data(), id: doc.id })));
    };
    fetchStudents();
  }, []);

  const handleLogin = (e) => {
    e.preventDefault();

    // Validate login credentials and class
    const student = students.find(
      (s) =>
        (s.email === emailOrUsername || s.username === emailOrUsername) &&
        s.password === password &&
        s.studentClass === studentClass
    );

    if (student) {
      setError(""); // Clear any previous errors
      // Redirect to the dashboard and optionally pass student data
      navigate("/studentDashboard", { state: { student } });
    } else {
      setError("Invalid email/username, password, or class!"); // Set error message
    }
  };

  return (
    <div className="login-container">
      <h2>Student Login</h2>
      <form onSubmit={handleLogin} className="login-form">
        <div className="form-group">
          <label htmlFor="emailOrUsername">Email or Username:</label>
          <input
            type="text"
            id="emailOrUsername"
            value={emailOrUsername}
            onChange={(e) => setEmailOrUsername(e.target.value)}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="password">Password:</label>
          <input
            type="password"
            id="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="studentClass">Class:</label>
          <select
            id="studentClass"
            value={studentClass}
            onChange={(e) => setStudentClass(e.target.value)}
            required
          >
            <option value="" disabled>
              Select Class
            </option>
            <option value="Primary 1">Primary 1</option>
            <option value="Primary 2">Primary 2</option>
            <option value="Primary 3">Primary 3</option>
            <option value="Primary 4">Primary 4</option>
            <option value="Primary 5">Primary 5</option>
            <option value="Primary 6">Primary 6</option>
            <option value="JSS 1">JSS 1</option>
            <option value="JSS 2">JSS 2</option>
            <option value="JSS 3">JSS 3</option>
            <option value="SSS 1">SSS 1</option>
            <option value="SSS 2">SSS 2</option>
            <option value="SSS 3">SSS 3</option>
          </select>
        </div>
        <button type="submit" className="login-btn">
          Login
        </button>
      </form>

      {error && <p className="error-message">{error}</p>} {/* Show error message */}
    </div>
  );
};

export default StudentLogin;
